@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class GuardianAudit {
 static final BlockPos BASE=FocalAudit.BASE.offset(120,0,0);static int ticks,checks;static volatile boolean ready,verified,gateDone;static EldritchGuardian g;static EldritchOrb testOrb;static net.minecraft.world.entity.animal.Cow cow;static int baseChecks;
 static void check(boolean v,String s){if(!v)throw new IllegalStateException("TC4_GUARDIAN FAIL "+s);System.out.println("TC4_GUARDIAN PASS "+s);}
 static void prepare(ServerPlayer p){check(AspectTable.get("tc4modern:eldritch_eye").equals(java.util.Map.of("alienis",5,"auram",3,"praecantatio",3,"sensus",3,"spiritus",3)),"original eldritcheye aspects");var l=p.serverLevel();p.server.setDifficulty(Difficulty.NORMAL,true);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);for(int x=-28;x<=28;x++)for(int z=-28;z<=28;z++){l.setBlock(BASE.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);for(int y=0;y<5;y++)l.setBlock(BASE.offset(x,y,z),Blocks.AIR.defaultBlockState(),3);}p.teleportTo(BASE.getX()+.5,BASE.getY(),BASE.getZ()+.5);p.setYRot(180);p.setXRot(0);p.setHealth(20);p.removeAllEffects();p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);for(int i=0;i<4;i++)BaublesInventory.of(p).setItem(i,ItemStack.EMPTY);for(var slot:EquipmentSlot.values())p.setItemSlot(slot,ItemStack.EMPTY);
  g=new EldritchGuardian(WarpEntities.ELDRITCH_GUARDIAN.get(),l);g.setPos(BASE.getX()+.5,BASE.getY(),BASE.getZ()-5.5);g.setNoAi(true);g.setYRot(0);g.setYHeadRot(0);g.setYBodyRot(0);l.addFreshEntity(g);check(g.getMaxHealth()==50&&g.getAttributeValue(Attributes.ATTACK_DAMAGE)==7&&g.getArmorValue()==4&&Math.abs(g.getAttributeValue(Attributes.MOVEMENT_SPEED)-.28)<.001,"original50hp7attack4armor28speed");check(g.getBbWidth()==.8f&&g.getBbHeight()==2.25f&&Math.abs(g.getEyeHeight()-2.1)<.001,"original dimensions and eyes");check(g.canBreatheUnderwater()&&g.getType().is(net.minecraft.tags.EntityTypeTags.UNDEAD),"underwaterbreathing and undeadtag");g.hurt(l.damageSources().magic(),10);check(Math.abs(g.getHealth()-45)<.001,"magicdamage halves before bypassarmor");g.invulnerableTime=0;g.hurt(l.damageSources().playerAttack(p),10);check(Math.abs(g.getHealth()-36.6)<.001,"original flat4armor ratio");g.setHealth(50);g.restrictTo(BASE,13);var tag=new CompoundTag();g.addAdditionalSaveData(tag);var copy=new EldritchGuardian(WarpEntities.ELDRITCH_GUARDIAN.get(),l);copy.readAdditionalSaveData(tag);check(copy.hasRestriction()&&copy.getRestrictCenter().equals(BASE)&&copy.getRestrictRadius()==13&&!copy.removeWhenFarAway(9999),"homeNBT persistence no despawn");check(EldritchGuardianRenderer.opacity(256,false)==.6f&&EldritchGuardianRenderer.opacity(1024,false)==0&&EldritchGuardianRenderer.opacity(576,true)==0,"original squared-distance opacity");
  int orbs=0;for(int i=0;i<60;i++){int before=l.getEntitiesOfClass(EldritchOrb.class,p.getBoundingBox().inflate(30)).size();g.performRangedAttack(p,1);int after=l.getEntitiesOfClass(EldritchOrb.class,p.getBoundingBox().inflate(30)).size();if(after>before)orbs++;}check(orbs>0&&p.hasEffect(MobEffects.WITHER)&&p.getEffect(MobEffects.WITHER).getDuration()==400,"real ranged attacks fireorbs and sonicwither400");check(PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)>0,"sonic adds temporarywarp");l.getEntitiesOfClass(EldritchOrb.class,p.getBoundingBox().inflate(40)).forEach(Entity::discard);p.removeAllEffects();
  var state=new WarpState();state.set(WarpState.Kind.PERMANENT,100);state.set(WarpState.Kind.STICKY,100);state.set(WarpState.Kind.TEMPORARY,10);state.setCounter(10000);long seed=0;for(;;seed++){var r=net.minecraft.util.RandomSource.create(seed);var roll=WarpEventRoll.check(100,100,10,10000,0,false,r::nextInt);if(roll.effect()==32)break;}PlayerWarp.save(p,state);l.random.setSeed(seed);var unmasked=WarpRuntime.check(p);check(unmasked.triggered()&&unmasked.effect()==32&&PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)==9,"actual dispatcher mist roll counter and temporarydecay");var helmet=new ItemStack(FortressArmor.item("helmet"));var mask=new CompoundTag();mask.putInt("mask",0);helmet.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(mask));p.setItemSlot(EquipmentSlot.HEAD,helmet);PlayerWarp.save(p,state);l.random.setSeed(seed);var masked=WarpRuntime.check(p);check(unmasked.effect()-masked.effect()>=2&&unmasked.effect()-masked.effect()<=5,"equipped grinning mask lowers real dispatcher effect2to5");check(net.minecraft.network.chat.Component.translatable(WarpEventPlan.select(32,100).message()).getString().equals(net.minecraft.network.chat.Component.translatable("warp.text.6").getString()),"single translation prefix");
  l.getEntitiesOfClass(EldritchGuardian.class,p.getBoundingBox().inflate(60),e->e!=g).forEach(Entity::discard);int spawned=WarpRuntime.mist(p,8);check(spawned==8,"real mist8guardians original50attempt solidtop search");var gs=l.getEntitiesOfClass(EldritchGuardian.class,p.getBoundingBox().inflate(60),e->e!=g);check(gs.stream().allMatch(e->e.getTarget()==p&&e.getAbsorptionAmount()==0),"mist targetplayer no finalizespawn");gs.forEach(Entity::discard);
  testOrb=new EldritchOrb(l,g);testOrb.setPos(g.getX(),g.getY()+1,g.getZ()+1);l.addFreshEntity(testOrb);cow=new net.minecraft.world.entity.animal.Cow(net.minecraft.world.entity.EntityType.COW,l);cow.setPos(g.getX()+1,g.getY(),g.getZ()+1);cow.setNoAi(true);l.addFreshEntity(cow);
  state=new WarpState();state.set(WarpState.Kind.TEMPORARY,5);PlayerWarp.save(p,state);p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);baseChecks=WarpRuntime.checks;p.tickCount=1999;ready=true;
 }
 static void gates(ServerPlayer p){var state=PlayerWarp.load(p);state.set(WarpState.Kind.STICKY,2);state.setCounter(97);PlayerWarp.save(p,state);WarpEventApplication.apply(p,WarpEventPlan.select(76,100));check(PlayerWarp.load(p).get(WarpState.Kind.STICKY)==1&&PlayerWarp.load(p).counter()==97,"stickyremoval preserves reduced counter");check(WarpRuntime.checks==baseChecks+1&&PlayerWarp.load(p).get(WarpState.Kind.TEMPORARY)==4,"NATURAL2000tick automatic cadence and missedroll decay");int before=WarpRuntime.checks;p.addEffect(new MobEffectInstance(WarpEffects.WARP_WARD,200));p.tickCount=2000;WarpRuntime.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));check(WarpRuntime.checks==before,"actual ward gate skips eventanddecay");p.removeAllEffects();gateDone=true;}
 static void sonic(ServerPlayer p){if(testOrb!=null&&testOrb.isAlive()){testOrb.onHit(new net.minecraft.world.phys.BlockHitResult(testOrb.position(),Direction.UP,BASE,false));check(cow.getHealth()<cow.getMaxHealth()&&cow.hasEffect(MobEffects.WEAKNESS)&&cow.getEffect(MobEffects.WEAKNESS).getDuration()==160,"real orbimpact AoEmagicdamage and weakness160");}g.getRandom().setSeed(0);while(true){long seed=g.getRandom().nextLong();var r=net.minecraft.util.RandomSource.create(seed);if(r.nextFloat()<=.1f){g.getRandom().setSeed(seed);break;}}g.performRangedAttack(p,1);verified=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.guardianAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var s=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)s.execute(()->prepare(s.getPlayerList().getPlayer(id)));if(ticks==120){check(ready,"server mechanics completed");s.execute(()->gates(s.getPlayerList().getPlayer(id)));}if(ticks==130){mc.player.setYRot(180);mc.player.setXRot(0);mc.options.hideGui=true;s.execute(()->sonic(s.getPlayerList().getPlayer(id)));}if(ticks==133)LiquidDeathAudit.shot(mc,"guardian-sonic.png");if(ticks==140){check(gateDone,"cadence gates completed");mc.player.setYRot(180);mc.player.setXRot(0);mc.options.hideGui=true;LiquidDeathAudit.shot(mc,"guardian-model-and-mist.png");}if(ticks==160){check(EldritchGuardianRenderer.rendered>0&&GuardianClient.wisps>0,"native originalmodel and wisp rendering");check(GuardianClient.sonics>0&&GuardianClient.sonicFrames>0&&GuardianClient.orbBursts>0&&WarpClientFog.state().active(),"real networksonic particles orb30wisps and warp fog");s.execute(()->sonic(s.getPlayerList().getPlayer(id)));}if(ticks==163)LiquidDeathAudit.shot(mc,"guardian-sonic.png");if(ticks==190){check(verified,"sonic verified");s.execute(()->{cow.setHealth(cow.getMaxHealth());cow.removeAllEffects();cow.setPos(g.getX(),g.getY(),g.getZ()-14);g.setNoAi(false);g.setTarget(cow);});}if(ticks==300)s.execute(()->{check(cow.getHealth()<cow.getMaxHealth()||cow.hasEffect(MobEffects.WEAKNESS)||cow.hasEffect(MobEffects.WITHER),"natural AI pursuit and ranged combat");g.setNoAi(true);verified=true;});if(ticks==320){System.out.println("TC4_GUARDIAN ALL PASS");mc.stop();}}
}
